def solve(L_km=5000, U=10) -> dict:
    # Convert length to meters
    L_m = L_km * 1000

    # Residence time is the time it takes for air to travel across the box
    # tau_out = L / U
    tau_out_s = L_m / U

    # Convert residence time from seconds to days
    tau_out_days = tau_out_s / (24 * 3600)

    return {
        "1": {"value": round(tau_out_days, 1), "unit": "days"}
    }

