def solve(A=1.0, P_bottom=80, P_top=30) -> dict:
    # Convert pressure from kPa to Pa (N/m^2)
    g = 9.8  # physical constant (frozen, not an input)
    P_bottom_pa = P_bottom * 1000
    P_top_pa = P_top * 1000

    # Calculate pressure difference
    delta_P = P_bottom_pa - P_top_pa

    # Calculate mass using hydrostatic relationship: delta_m = (A / g) * delta_P
    delta_m = (A / g) * delta_P

    return {
        "1": {"value": round(delta_m), "unit": "kg"}
    }

