def solve(M=10.0, T_sfc=30.0, T_air=15.0, C_H=0.01) -> dict:
    # Effective surface kinematic heat flux: F_H = C_H * M * (T_sfc - T_air)
    # The temperature difference in Celsius is equivalent to the difference in Kelvin
    F_H = C_H * M * (T_sfc - T_air)

    return {
        "1": {"value": F_H, "unit": "K m s^{-1}"}
    }

def solve(F_H=0.67, z_i_km=1.0, T_v=298.0) -> dict:
    g = 9.8  # physical constant (frozen, not an input)
    import math

    # Unit conversions
    z_i = z_i_km * 1000.0  # km to m

    # Deardorff velocity formula: w_* = [ (g / T_v) * z_i * F_H ]^(1/3)
    # It represents the convective velocity scale in the boundary layer.
    w_star = ((g / T_v) * z_i * F_H) ** (1.0 / 3.0)

    return {
        "1": {"value": w_star, "unit": "m s^-1"}
    }

