def solve(A=0.3) -> dict:
    # The Earth intercepts solar radiation over its cross-sectional area (pi * r^2)
    # but distributes it over its entire surface area (4 * pi * r^2).
    # Therefore, the average incoming solar radiation is S_0 / 4.
    # The absorbed fraction is (1 - A).
    # Formula: E_in = (S_0 / 4) * (1 - A)
    S_0 = 1350.0  # physical constant (frozen, not an input)
    E_in = (S_0 / 4.0) * (1.0 - A)

    return {
        "1": {"value": E_in, "unit": "W m^{-2}"}
    }

