    # chi = (Q / (pi * sigma_y * sigma_z * u)) * exp(-0.5 * (H / sigma_z)^2)
    chi = (Q / (math.pi * sigma_y * sigma_z * u)) * math.exp(-0.5 * (H / sigma_z)**2)

    return {
        "1": {"value": chi, "unit": "g/m^3"}
    }

def solve(Q=80, H=60, u=6, x=500, sigma_y=36, sigma_z=18.5, y=50) -> dict:
    import math

    # Calculate the ground-level concentration at a crosswind distance y
    # Formula: chi = (Q / (pi * sigma_y * sigma_z * u)) * exp(-0.5 * (y / sigma_y)^2) * exp(-0.5 * (H / sigma_z)^2)
    chi = (Q / (math.pi * sigma_y * sigma_z * u)) * \
          math.exp(-0.5 * (y / sigma_y)**2) * \
          math.exp(-0.5 * (H / sigma_z)**2)

    return {
        "1": {"value": chi, "unit": "g/m^3"}
    }

