def solve(coal_rate_tons_per_hr=10, sulfur_fraction=0.03, lbs_per_ton=2000, g_per_lb=453.6, s_per_hr=3600, mw_s=32, mw_so2=64) -> dict:
    # Convert coal burn rate from tons/hour to grams/second
    coal_rate_g_per_s = (coal_rate_tons_per_hr * lbs_per_ton * g_per_lb) / s_per_hr

    # Calculate the mass rate of sulfur being burned
