    # Calculate SO2 emission rate assuming 100% conversion of S to SO2
    # Mass of SO2 = Mass of S * (Molecular Weight of SO2 / Molecular Weight of S)
    so2_rate_g_per_s = s_rate_g_per_s * (mw_so2 / mw_s)

    return {
        "1": {"value": so2_rate_g_per_s, "unit": "g/s"}
    }

