def solve(u_a=1.0, u_b=10.0, f0=1e-4) -> dict:
    # The equations for pure inertial oscillations yield a circular trajectory
    # with radius R = V / |f0|, where V is the particle speed and f0 is the Coriolis parameter.

    # Part (a): Particle speed of 1 m/s
    R_a_m = u_a / f0
    R_a_km = R_a_m / 1000.0  # Convert meters to kilometers

    # Part (b): Particle speed of 10 m/s
    R_b_m = u_b / f0
    R_b_km = R_b_m / 1000.0  # Convert meters to kilometers

    return {
        "a": {"value": R_a_km, "unit": "km"},
        "b": {"value": R_b_km, "unit": "km"}
    }

