def solve(G_f_HNO3=-74.7, G_f_OH=34.2, G_f_NO3=115.8, G_f_H2O=-228.4) -> dict:
    # Calculate the change in Gibbs free energy for the reaction
    # Delta G_rxn = sum(G_f(products)) - sum(G_f(reactants))
    # A reaction is spontaneous if Delta G_rxn < 0.

    G_products = G_f_HNO3 + G_f_OH
    G_reactants = G_f_NO3 + G_f_H2O

    delta_G = G_products - G_reactants

    return {
        "1": {"value": round(delta_G, 1), "unit": "kJ/mol"}
    }

