def solve(H=7.5, rho_0=1.25, p_0=1000, rho_target=1, p_target=1) -> dict:
    # Calculate height for target density: z = -H * ln(rho / rho_0)
    z_a = -H * math.log(rho_target / rho_0)

    # Calculate height for target pressure: z = -H * ln(p / p_0)
    z_b = -H * math.log(p_target / p_0)

    return {
        "a": {"value": z_a, "unit": "km"},
        "b": {"value": z_b, "unit": "km"}
    }

