def solve(delta_p_hPa=1.0, rho_0=1.25, U_e=5.0) -> dict:
    # Convert pressure surge amplitude from hPa to Pa
    delta_p = delta_p_hPa * 100.0

    # Solve for U_f from the formula: delta_p = rho_0 * (U_f - U_e)^2
    # Assuming U_f > U_e, we take the positive root: U_f = U_e + sqrt(delta_p / rho_0)
    U_f = U_e + math.sqrt(delta_p / rho_0)

    return {
        "1": {"value": round(U_f, 2), "unit": "m s^-1"}
