def solve(w1=33.0, d1=1.0, w2=33.0, d2=5.0, w3=34.0, d3=10.0, dcut=5.0):
    # Eq. (9.21): efficiency = 1 / (1 + (Dcut/D)^2)
    def eff(d):
        return 1.0 / (1.0 + (dcut / d) ** 2)

    total_weight = w1 + w2 + w3
