def solve(P1=100.0, v1=0.0, v2=10.0, T_C=0.0) -> dict:
    R = 287.0  # physical constant (frozen, not an input)
    T_K = T_C + 273.15 # Temperature in K

    # Bernoulli's equation for compressible isothermal flow:
    # v1^2 / 2 + R * T * ln(P1) = v2^2 / 2 + R * T * ln(P2)
    # Solving for P2:
    P2 = P1 * math.exp((v1**2 - v2**2) / (2 * R * T_K))

    return {
        "1": {"value": round(P2, 2), "unit": "kPa"}
    }

