def solve(r1=1e-6, r2=10e-6, r3=100e-6, d=1000.0, eta=1.7e-5, rho_w=1000.0) -> dict:
    # Terminal velocity (Stokes): v = 2 r^2 rho_w g / (9 eta); fall time = d/v.
