def solve(rho_water=1000, C_liq=4200, V_can=354, L_cond=2.5e6, delta_T=15) -> dict:
    # Heat required to warm the soda: Q = m_soda * C_liq * delta_T
    # Heat released by condensation: Q = m_cond * L_cond
    # Equating the two: m_cond * L_cond = m_soda * C_liq * delta_T
    # Since m = rho * V, and rho is the same for both:
    # V_cond * L_cond = V_can * C_liq * delta_T

    V_cond = (V_can * C_liq * delta_T) / L_cond

    return {
        "1": {"value": round(V_cond, 2), "unit": "ml"},
    }

